   100|export async function startSeniorDevWorker(): Promise<void> {
   101|  console.log('[IVX-SENIOR-DEV-01] Worker starting', { workerId: IVX_SENIOR_DEV_WORKER_ID, at: state.startedAt });
   102|  // Self-bootstrap the worker tables via Supabase Management API (same proven
