   175|async function recoverOrphanedTasks(): Promise<void> {
   176|  const tasks = await listTasks(100);
   177|  const now = Date.now();
   178|  const stale: IVXOwnerAITaskRow[] = [];
   179|  for (const t of tasks) {
   180|    const isSeniorDev = (t.task_type === 'senior_dev')
   181|      || (typeof t.trace_id === 'string' && t.trace_id.startsWith('senior-dev-'));
   182|    if (!isSeniorDev) continue;
   183|    if (t.status !== 'RUNNING' && t.status !== 'WAITING_APPROVAL' && t.status !== 'COMMITTING') continue;
   184|    // If the task already has a commit_sha, it did real work — the worker just
   185|    // got killed (likely by its own Render deploy restarting the runtime) before
   186|    // reaching VERIFIED. Mark it terminal FAILED with the real evidence it has,
   187|    // rather than re-running the whole pipeline (which would re-plan, re-implement,
   188|    // and either no-op or duplicate-commit). This also unblocks single-flight
   189|    // for the next queued task.
   190|    if (t.commit_sha) {
   191|      console.log('[IVX-SENIOR-DEV-01] Orphaned task already committed — marking terminal', { taskId: t.id, commitSha: t.commit_sha, status: t.status });
   192|      await patchTask(t.id, {
   193|        status: 'FAILED',
   194|        checkpoint: 'FAILED (orphaned after commit — worker killed by self-deploy restart before LIVE_VERIFYING)',
   195|        error_message: `Worker restarted mid-task after commit ${t.commit_sha}. The commit is real and on GitHub; the task just did not reach VERIFIED because the worker process was killed by its own Render deploy triggering a runtime restart. File(s) changed: ${JSON.stringify(t.files_changed ?? [])}.`,
   196|        checkpoint_history: appendCheckpoint(null, `ORPHAN_TERMINATED_WITH_COMMIT at ${new Date().toISOString()} (commitSha=${t.commit_sha})`),
   197|      });
   198|      continue;
   199|    }
   200|    const hb = t.heartbeat_at ? new Date(t.heartbeat_at).getTime() : 0;
   201|    if (now - hb > TASK_CLAIM_TIMEOUT_MS) stale.push(t);
   202|  }
   203|  for (const s of stale) {
   204|    console.log('[IVX-SENIOR-DEV-01] Requeuing orphaned task', { taskId: s.id, status: s.status, heartbeatAt: s.heartbeat_at });
   205|    await patchTask(s.id, {
   206|      status: 'RETRYING',
   207|      checkpoint: 'RETRYING (orphan recovered — stale heartbeat)',
   208|      checkpoint_history: appendCheckpoint(null, `ORPHAN_RECOVERED at ${new Date().toISOString()}`),
   209|    });
   210|  }
   211|}
